"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
// ★ useAuthからisLoadingを取得できるように修正
import { useAuth } from "@/hooks/useAuth";

export default function LoginPage() {
  const router = useRouter();
  // ★ isLoadingも取得
  const { login, isAuthenticated, isLoading } = useAuth();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [apiError, setApiError] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // 💡 AuthProviderがisLoading=trueの間はローディング画面を表示するため、
  // ここでのレンダリングがスキップされる可能性がありますが、念のためチェック
  if (!isLoading && isAuthenticated) {
    router.push("/");
    return null; // レンダリングを停止
  }

  // 認証情報確認中にログインフォームを見せない
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white">
        <p>認証状態を確認中...</p>
      </div>
    );
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setApiError("");
    setIsSubmitting(true);

    // 簡易バリデーション (Nuxt/VeeValidateの代替)
    if (!email || !password) {
      setApiError("メールアドレスとパスワードを入力してください。");
      setIsSubmitting(false);
      return;
    }

    try {
      await login({ email, password });
      // ログイン成功後はuseAuthフック内でリダイレクトされる
    } catch (error: any) {
      console.error("Login attempt failed:", error);

      let errorMessage =
        "ログインに失敗しました。時間をおいて再度お試しください。";

      if (error.code) {
        switch (error.code) {
          case "auth/user-not-found":
          case "auth/wrong-password":
          case "auth/invalid-credential":
            errorMessage = "メールアドレスまたはパスワードが正しくありません。";
            break;
          case "auth/invalid-email":
            errorMessage = "メールアドレスの形式が正しくありません。";
            break;
          case "auth/too-many-requests":
            errorMessage =
              "短時間にログインが集中しています。しばらく待ってからお試しください。";
            break;
          default:
            errorMessage = `ログインに失敗しました: ${error.message}`;
            break;
        }
      }

      setApiError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="w-full max-w-xl p-8 bg-white rounded-xl shadow-2xl mx-auto z-10 mt-20 mb-8">
      {/* Title */}
      <h2 className="text-center text-3xl font-bold text-gray-800 mb-6 border-b pb-3">
        ログイン
      </h2>

      {/* API Error */}
      {apiError && (
        <div className="mb-4 p-3 bg-red-100 text-red-700 rounded text-sm font-medium">
          {apiError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Email Field */}
        <div>
          <label
            htmlFor="email"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            メールアドレス
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            autoComplete="email"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* Password Field */}
        <div>
          <label
            htmlFor="password"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            パスワード
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            autoComplete="current-password"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* Submit Button */}
        <div className="pt-2">
          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full bg-red-600 text-white py-3 rounded-lg font-semibold text-lg hover:bg-red-700 transition duration-150 shadow-lg disabled:bg-gray-400 disabled:cursor-not-allowed"
          >
            {isSubmitting ? "ログイン中..." : "ログインする"}
          </button>
        </div>
      </form>

      {/* Register Link */}
      <div className="mt-6 text-center">
        <Link
          href="/register"
          className="text-sm text-blue-500 hover:text-blue-700 transition duration-150 font-medium"
        >
          会員登録はこちら
        </Link>
      </div>
    </div>
  );
}
